import type { Song } from '../types';

type SongTuple = [
  string, // title
  string, // artist
  number, // year
  string, // decade
  number, // bpm
  string, // key
  string, // genre
  'M' | 'F' | 'X' | 'I', // vocal: Male/Female/Mixed/Instrumental
  'L' | 'M' | 'H', // energy
  number, // flags: bitfield [singalong, horn, keys, guitar, dance_hi, dance_med]
  string, // notes
];

const VOCAL_MAP = { M: 'Male', F: 'Female', X: 'Mixed', I: 'Instrumental' } as const;
const ENERGY_MAP = { L: 'Low', M: 'Medium', H: 'High' } as const;

function makeSong(t: SongTuple): Song {
  const flags = t[9];
  return {
    id: t[0].toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+$/, ''),
    title: t[0],
    artist: t[1],
    year: t[2],
    decade: t[3],
    bpm: t[4],
    key: t[5],
    time_signature: '4/4',
    genre: t[6],
    vocal_gender: VOCAL_MAP[t[7]],
    energy: ENERGY_MAP[t[8]],
    crowd_singalong: !!(flags & 32),
    horn_friendly: !!(flags & 16),
    keyboard_driven: !!(flags & 8),
    guitar_driven: !!(flags & 4),
    danceability: (flags & 2) ? 'High' : (flags & 1) ? 'Medium' : 'Low',
    notes: t[10],
  };
}

